import tsParser from "@typescript-eslint/parser";

export default [
  { ignores: ["dist/**", "node_modules/**", "test-results/**", "playwright-report/**"] },
  {
    files: ["**/*.{ts,tsx,js,mjs,cjs}"],
    languageOptions: {
      parser: tsParser,
      parserOptions: { ecmaVersion: "latest", sourceType: "module", ecmaFeatures: { jsx: true } },
    },
    rules: {
      "no-debugger": "error",
      "no-dupe-args": "error",
      "no-dupe-else-if": "error",
      "no-unreachable": "error",
      "no-unsafe-finally": "error",
      "no-sparse-arrays": "error",
    },
  },
];

import { text, renderMessage, type Locale } from "@ai-werewolf-arena/game-text";
import { ReplayLoadError } from "../src/replay/offline-replay";

const codes = [
  "replay_dev_usage",
  "replay_render_input_output_required",
  "replay_render_source_overwrite",
  "replay_render_output_exists",
  "replay_frame_invalid",
  "replay_render_output_extension_invalid",
  "replay_frame_out_of_range",
  "replay_render_and_cleanup_failed",
  "replay_display_locale_invalid",
  "replay_display_time_zone_invalid",
] as const;
function loaderMessage(error: unknown, locale: Locale): string | undefined {
  try {
    if (!(error instanceof ReplayLoadError)) return undefined;
    const ref = Object.getOwnPropertyDescriptor(error, "messageRef")?.value;
    if (!ref || typeof ref !== "object") return undefined;
    const fields = Object.getOwnPropertyDescriptors(ref);
    if (
      Object.entries(fields).some(
        ([key, field]) => !["key", "parameters"].includes(key) || !("value" in field),
      )
    )
      return undefined;
    const key = fields.key?.value;
    if (
      ![
        "replay.invalid_file",
        "replay.missing_fields",
        "replay.unsupported_version",
        "replay.read_failed",
        "replay.http_failed",
      ].includes(key)
    )
      return undefined;
    const parameters = fields.parameters?.value;
    if (key === "replay.http_failed") {
      if (!parameters || typeof parameters !== "object") return undefined;
      const params = Object.getOwnPropertyDescriptors(parameters);
      const status = params.status?.value;
      if (
        Object.keys(params).length !== 1 ||
        typeof status !== "number" ||
        !Number.isInteger(status) ||
        status < 100 ||
        status > 599
      )
        return undefined;
      return renderMessage(locale, { key: "replay.http_failed", parameters: { status } });
    }
    if (
      parameters !== undefined &&
      (!parameters ||
        typeof parameters !== "object" ||
        Object.getOwnPropertyNames(parameters).length)
    )
      return undefined;
    return renderMessage(locale, { key });
  } catch {
    return undefined;
  }
}

/** Only local IDs and local loader messages may cross this CLI output boundary. */
export function replayCommandFailure(error: unknown, locale: Locale) {
  let candidate: unknown;
  try {
    candidate =
      error && typeof error === "object"
        ? Object.getOwnPropertyDescriptor(error, "message")?.value
        : undefined;
  } catch {
    /* foreign object */
  }
  const code =
    typeof candidate === "string" && codes.includes(candidate as (typeof codes)[number])
      ? candidate
      : "replay_command_failed";
  const message = loaderMessage(error, locale) ?? text(locale, "cli.offline_failed", { code });
  return { code, message };
}

import { bundle } from "@remotion/bundler";
import { openBrowser, renderMedia, renderStill, selectComposition } from "@remotion/renderer";
import { parseArgs } from "node:util";
import { mkdtemp, mkdir, readFile, rm, lstat, link } from "node:fs/promises";
import path from "node:path";
import type { Locale } from "@ai-werewolf-arena/game-text";
import { replayCommandFailure } from "./cli_error";
import { isLocale } from "@ai-werewolf-arena/game-catalog";
import { resolveReplayInput } from "./replay-dev";
import { parseOfflineReplayJson } from "../src/replay/offline-replay";
import { createReplayRenderInput, FRAMES_PER_EVENT } from "../src/replay/replay-frame";
import { DEFAULT_REPLAY_TIME_ZONE } from "../src/replay/replay-display";

const defaultRendering = { bundle, openBrowser, selectComposition, renderStill, renderMedia };
export async function renderReplay(
  args: string[],
  rendering = defaultRendering,
  display?: { locale: Locale },
) {
  const { values } = parseArgs({
    args: args[0] === "--" ? args.slice(1) : args,
    options: {
      input: { type: "string" },
      output: { type: "string" },
      locale: { type: "string" },
      "time-zone": { type: "string" },
      frame: { type: "string" },
      browser: { type: "string" },
    },
    strict: true,
    allowPositionals: false,
  });
  if (display && isLocale(values.locale)) display.locale = values.locale;
  if (!values.input || !values.output) throw new Error("replay_render_input_output_required");
  const source = resolveReplayInput(values.input);
  const output = path.resolve(values.output);
  if (path.resolve(source) === output) throw new Error("replay_render_source_overwrite");
  // Refuse existing outputs, including symlinks/hard links, before bundling or opening a browser.
  try {
    await lstat(output);
    throw new Error("replay_render_output_exists");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }
  const replay = parseOfflineReplayJson(await readFile(source, "utf8"));
  const locale = values.locale ?? replay.meta.locale ?? "zh-CN";
  if (!isLocale(locale)) throw new Error("replay_display_locale_invalid");
  if (display) display.locale = locale;
  const inputProps = {
    ...createReplayRenderInput(replay, {
      locale,
      timeZone: values["time-zone"] ?? DEFAULT_REPLAY_TIME_ZONE,
    }),
  };
  const still = values.frame !== undefined;
  const frame = still ? Number(values.frame) : undefined;
  if (still && (!/^\d+$/.test(values.frame!) || !Number.isSafeInteger(frame)))
    throw new Error("replay_frame_invalid");
  if (path.extname(output) !== (still ? ".png" : ".mp4"))
    throw new Error("replay_render_output_extension_invalid");
  if (
    frame !== undefined &&
    frame >= Math.max(inputProps.replay.events.length * FRAMES_PER_EVENT, 1)
  )
    throw new Error("replay_frame_out_of_range");
  await mkdir(path.dirname(output), { recursive: true });
  // Keep the artifact on the target file system so link() publishes it atomically and exclusively.
  const temporary = await mkdtemp(path.join(path.dirname(output), ".awa-replay-render-"));
  const artifact = path.join(temporary, still ? "artifact.png" : "artifact.mp4");
  let browser: Awaited<ReturnType<typeof openBrowser>> | undefined;
  const errors: unknown[] = [];
  try {
    const serveUrl = await rendering.bundle({
      entryPoint: path.resolve(import.meta.dir, "../src/replay/remotion-entry.tsx"),
      outDir: path.join(temporary, "bundle"),
    });
    browser = await rendering.openBrowser("chrome", {
      browserExecutable: values.browser,
      logLevel: "error",
    });
    const common = { serveUrl, inputProps, puppeteerInstance: browser, logLevel: "error" as const };
    const composition = await rendering.selectComposition({ ...common, id: "Replay" });
    if (frame !== undefined && frame >= composition.durationInFrames)
      throw new Error("replay_frame_out_of_range");
    if (still)
      await rendering.renderStill({
        ...common,
        composition,
        frame,
        output: artifact,
        imageFormat: "png",
        overwrite: false,
      });
    else
      await rendering.renderMedia({
        ...common,
        composition,
        codec: "h264",
        outputLocation: artifact,
        concurrency: 2,
        overwrite: false,
      });
    try {
      await link(artifact, output);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EEXIST")
        throw new Error("replay_render_output_exists");
      throw error;
    }
  } catch (error) {
    errors.push(error);
  } finally {
    if (browser) {
      try {
        await browser.close({ silent: true });
      } catch (error) {
        errors.push(error);
      }
    }
    try {
      await rm(temporary, { recursive: true, force: true });
    } catch (error) {
      errors.push(error);
    }
  }
  if (errors.length === 1) throw errors[0];
  if (errors.length > 1) throw new AggregateError(errors, "replay_render_and_cleanup_failed");
}
if (import.meta.main) {
  const display: { locale: Locale } = { locale: "zh-CN" };
  try {
    await renderReplay(process.argv.slice(2), defaultRendering, display);
  } catch (error) {
    console.error(JSON.stringify(replayCommandFailure(error, display.locale)));
    process.exitCode = 1;
  }
}

import { isLocale } from "@ai-werewolf-arena/game-catalog";
import type { Locale } from "@ai-werewolf-arena/game-text";
import { replayCommandFailure } from "./cli_error";
import { existsSync, statSync } from "node:fs";
import path from "node:path";

export function resolveReplayInput(input: string, cwd: string = process.cwd()): string {
  const resolved = path.resolve(cwd, input);
  if (!existsSync(resolved)) {
    throw new Error(`Replay input not found: ${resolved}`);
  }
  const replayPath = statSync(resolved).isDirectory()
    ? path.join(resolved, "replay.json")
    : resolved;
  if (!existsSync(replayPath) || !statSync(replayPath).isFile()) {
    throw new Error(`Replay file not found: ${replayPath}`);
  }
  return replayPath;
}

if (import.meta.main) {
  let locale: Locale = "zh-CN";
  try {
    const argv = process.argv.slice(2),
      args = argv[0] === "--" ? argv.slice(1) : argv;
    let input: string | undefined;
    for (let index = 0; index < args.length; index += 2) {
      const value = args[index + 1];
      if (!value || value.startsWith("--")) throw new Error("replay_dev_usage");
      if (args[index] === "--input") input = value;
      else if (args[index] === "--display-locale") {
        if (!isLocale(value)) throw new Error("replay_display_locale_invalid");
        locale = value;
      } else throw new Error("replay_dev_usage");
    }
    if (!input) throw new Error("replay_dev_usage");
    const replayPath = resolveReplayInput(input);
    const child = Bun.spawn(["bunx", "vite"], {
      cwd: process.cwd(),
      env: { ...process.env, AWA_REPLAY_INPUT: replayPath },
      stdin: "inherit",
      stdout: "inherit",
      stderr: "inherit",
    });
    process.exitCode = await child.exited;
  } catch (error) {
    console.error(JSON.stringify(replayCommandFailure(error, locale)));
    process.exitCode = 1;
  }
}

import { createReadStream, existsSync } from "node:fs";
import { fileURLToPath, URL } from "node:url";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [
    react(),
    {
      name: "replay-input-endpoint",
      configureServer(server) {
        const replayPath = process.env.AWA_REPLAY_INPUT;
        server.middlewares.use("/api/replay", (request, response, next) => {
          if (request.method !== "GET") return next();
          if (!replayPath || !existsSync(replayPath)) {
            response.statusCode = 404;
            response.setHeader("content-type", "application/json; charset=utf-8");
            response.end(JSON.stringify({ error: "replay_input_not_configured" }));
            return;
          }
          response.statusCode = 200;
          response.setHeader("content-type", "application/json; charset=utf-8");
          response.setHeader("cache-control", "no-store");
          createReadStream(replayPath).pipe(response);
        });
      },
    },
  ],
  resolve: {
    alias: {
      "@": fileURLToPath(new URL("./src", import.meta.url)),
    },
  },
  server: {
    port: 5173,
    host: true,
  },
});

import { useEffect, useState } from "react";
import { text, renderMessage, type Locale } from "@ai-werewolf-arena/game-text";
import { loadReplay, type ReplayLoadState } from "./replay/offline-replay";
import { ReplayWorkspace } from "./replay/ReplayWorkspace";
import { ReplayDisplayControls } from "./replay/ReplayDisplayControls";
import { DEFAULT_REPLAY_TIME_ZONE, type ReplayDisplayOptions } from "./replay/replay-display";

function App() {
  const [state, setState] = useState<ReplayLoadState>({ status: "loading" });
  const [selectedLocale, setSelectedLocale] = useState<Locale | null>(null);
  const [timeZone, setTimeZone] = useState(DEFAULT_REPLAY_TIME_ZONE);
  const locale =
    selectedLocale ?? (state.status === "ready" ? state.replay.meta.locale : undefined) ?? "zh-CN";
  const display = { locale, timeZone };
  const onDisplayChange = (next: Partial<ReplayDisplayOptions>) => {
    if (next.locale !== undefined) setSelectedLocale(next.locale);
    if (next.timeZone !== undefined) setTimeZone(next.timeZone);
  };

  useEffect(() => {
    let active = true;
    void loadReplay().then((value) => {
      if (active) setState(value);
    });
    return () => {
      active = false;
    };
  }, []);
  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  if (state.status === "ready")
    return (
      <ReplayWorkspace replay={state.replay} display={display} onDisplayChange={onDisplayChange} />
    );
  return (
    <main className="shell centered">
      <section className={state.status === "error" ? "load-error" : "empty-state"}>
        <ReplayDisplayControls display={display} onChange={onDisplayChange} />
        {state.status === "loading" && <p>{text(locale, "replay.loading")}</p>}
        {state.status === "error" && (
          <>
            <h1>{text(locale, "replay.load_error")}</h1>
            <p>{renderMessage(locale, state.message)}</p>
          </>
        )}
        {state.status === "missing" && (
          <>
            <p className="eyebrow">{text(locale, "replay.workbench")}</p>
            <h1>{text(locale, "replay.title")}</h1>
            <p>{text(locale, "replay.empty")}</p>
            <code>bun run replay:dev -- --input /absolute/path/to/game.replay.json</code>
          </>
        )}
      </section>
    </main>
  );
}
export default App;

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./style.css";

createRoot(document.getElementById("app")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { text, type Locale } from "@ai-werewolf-arena/game-text";
import type { ReplayEvent } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "./event-labels";
import { phaseName, eventStageName } from "./replay-localization";

interface EventTimelineProps {
  events: ReplayEvent[];
  locale: Locale;
  playerIds: readonly number[];
  activeEventSeq: number | null;
  focusedPlayerId: number | null;
  onJumpTo: (index: number) => void;
  onClearFocus: () => void;
}

export function EventTimeline({
  events,
  locale,
  playerIds,
  activeEventSeq,
  focusedPlayerId,
  onJumpTo,
  onClearFocus,
}: EventTimelineProps) {
  return (
    <section className="panel timeline">
      <div className="panel-heading">
        <div>
          <p className="section-kicker">{text(locale, "replay.kicker.timeline")}</p>
          <h2>
            {focusedPlayerId === null
              ? text(locale, "replay.timeline")
              : text(locale, "replay.player_timeline", { id: focusedPlayerId })}
          </h2>
        </div>
        {focusedPlayerId !== null && (
          <button type="button" className="text-button" onClick={onClearFocus}>
            {text(locale, "replay.clear_focus")}
          </button>
        )}
      </div>
      <div className="timeline-list">
        {events.map((event, index) => (
          <button
            type="button"
            className={`event ${event.seq === activeEventSeq ? "active" : ""}`}
            key={event.seq}
            onClick={() => onJumpTo(index)}
          >
            <span className="event-marker">D{event.day}</span>
            <div>
              <div className="event-head">
                <span>
                  #{event.seq} · {phaseName(event.phase, locale)}
                </span>
                <span>{eventStageName(event, locale, playerIds)}</span>
              </div>
              <p>{eventLabel(event, locale, playerIds)}</p>
            </div>
          </button>
        ))}
      </div>
    </section>
  );
}

import { text, type Locale } from "@ai-werewolf-arena/game-text";
import type { ReplayPlayerState } from "./replay-projection";
import { campName, roleName } from "./replay-localization";

interface PlayerSeatsProps {
  players: ReplayPlayerState[];
  locale: Locale;
  focusedPlayerId: number | null;
  onToggleFocus: (playerId: number) => void;
}

export function PlayerSeats({ players, locale, focusedPlayerId, onToggleFocus }: PlayerSeatsProps) {
  const aliveCount = players.filter((player) => player.alive).length;

  return (
    <section className="panel player-panel">
      <div className="panel-heading compact">
        <div>
          <p className="section-kicker">{text(locale, "replay.kicker.seats")}</p>
          <h2>{text(locale, "replay.seats")}</h2>
        </div>
        <span>{text(locale, "replay.alive", { count: aliveCount })}</span>
      </div>
      <div className="seat-grid">
        {players.map((player) => (
          <button
            type="button"
            key={player.playerId}
            aria-label={`${text(locale, "replay.player", { id: player.playerId })}${player.name ? ` · ${player.name}` : ""}`}
            className={`seat ${player.alive ? "alive" : "dead"} ${player.isWinner ? "winner-seat" : ""} ${player.camp} ${focusedPlayerId === player.playerId ? "focused" : ""}`}
            onClick={() => onToggleFocus(player.playerId)}
          >
            <span className="seat-number">{player.playerId}</span>
            {player.isSheriff && (
              <span className="sheriff">{text(locale, "replay.sheriff_short")}</span>
            )}
            {player.isWinner && (
              <span className="winner">{text(locale, "victory.winner_badge")}</span>
            )}
            {player.name && <span className="seat-name">{player.name}</span>}
            <strong>{roleName(player.role, locale)}</strong>
            <small>{campName(player.camp, locale)}</small>
            {player.publicRole && (
              <small>
                {text(locale, "replay.role_revealed_badge", {
                  role: roleName(player.publicRole, locale),
                })}
              </small>
            )}
          </button>
        ))}
      </div>
    </section>
  );
}

import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { buildReplayFrame, FRAMES_PER_EVENT, type ReplayRenderInput } from "./replay-frame";
export { FRAMES_PER_EVENT } from "./replay-frame";

export function ReplayComposition(input: ReplayRenderInput) {
  const frame = useCurrentFrame();
  return <ReplayFrame input={input} frame={frame} />;
}

/** The exact frame view used by the Player and offline composition. */
export function ReplayFrame({ input, frame }: { input: ReplayRenderInput; frame: number }) {
  const view = buildReplayFrame(input, frame);
  // A sealed result has a longer caption and winner rows; reserve room below its seats.
  const seatCenter = view.snapshot.decision ? 33 : 38;
  const seatRadius = view.snapshot.decision ? 17 : 21;
  const fade = interpolate(frame % FRAMES_PER_EVENT, [0, 10, 72, 90], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        background: "radial-gradient(circle at 50% 45%, #263d58 0, #101b2a 42%, #060a11 100%)",
        color: "#f6f0df",
        fontFamily: "Inter, ui-sans-serif, system-ui",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 32,
          border: "1px solid rgba(224,188,111,.25)",
          borderRadius: 28,
        }}
      />
      <div
        style={{
          position: "absolute",
          top: 58,
          left: 72,
          color: "#e4c67d",
          fontSize: 19,
          fontWeight: 700,
          letterSpacing: 4,
        }}
      >
        AI WEREWOLF ARENA
      </div>
      <div
        data-testid="composition-phase"
        style={{ position: "absolute", top: 56, right: 72, color: "#a9b8cb", fontSize: 20 }}
      >
        {view.dayPhase}
      </div>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: `${seatCenter}%`,
          width: 430,
          height: 250,
          transform: "translate(-50%, -50%)",
          borderRadius: "50%",
          border: "1px solid rgba(228,198,125,.5)",
          background: "radial-gradient(ellipse, #24384b, #101923 70%)",
          boxShadow: "0 0 70px rgba(228,198,125,.1)",
        }}
      />
      {view.players.map((player, index) => {
        const angle = (Math.PI * 2 * index) / view.players.length - Math.PI / 2;
        const left = 50 + Math.cos(angle) * 38;
        const top = seatCenter + Math.sin(angle) * seatRadius;
        return (
          <div
            key={player.playerId}
            data-composition-player={player.playerId}
            data-testid={player.isWinner ? "composition-winner" : undefined}
            style={{
              position: "absolute",
              left: `${left}%`,
              top: `${top}%`,
              transform: "translate(-50%, -50%)",
              width: 114,
              textAlign: "center",
              opacity: player.alive ? 1 : player.isWinner ? 0.75 : 0.35,
            }}
          >
            <div
              style={{
                width: 48,
                height: 48,
                margin: "0 auto 7px",
                display: "grid",
                placeItems: "center",
                borderRadius: "50%",
                border: `2px solid ${player.camp === "wolf" ? "#df7771" : "#75bbd7"}`,
                background: "#0d1620",
                fontSize: 22,
                fontWeight: 800,
              }}
            >
              {player.playerId}
            </div>
            {player.name && (
              <div style={{ fontSize: 14, overflowWrap: "anywhere" }}>{player.name}</div>
            )}
            <div style={{ fontSize: 15, fontWeight: 700 }}>
              {player.roleLabel}
              {player.sheriffLabel ? ` · ${player.sheriffLabel}` : ""}
            </div>
            {player.isWinner && (
              <div style={{ color: "#e4c67d", fontSize: 14 }}>{view.winnerLabel}</div>
            )}
          </div>
        );
      })}
      <div
        data-testid="composition-caption"
        style={{
          position: "absolute",
          left: 92,
          right: 92,
          bottom: 62,
          padding: "20px 24px",
          borderRadius: 16,
          background: "rgba(6,10,17,.82)",
          border: "1px solid rgba(231,216,179,.14)",
          opacity: fade,
        }}
      >
        <div style={{ color: "#e4c67d", fontSize: 14, letterSpacing: 2, marginBottom: 8 }}>
          {view.stage} · {view.time}
        </div>
        <div
          data-testid="composition-event"
          data-event-seq={view.eventSeq ?? ""}
          style={{ fontSize: 27, lineHeight: 1.35, fontWeight: 650 }}
        >
          {view.label}
        </div>
        {view.victory && (
          <div
            data-testid="composition-victory"
            style={{ marginTop: 8, color: "#e4c67d", fontSize: 18 }}
          >
            {view.victory}
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
}

import { text } from "@ai-werewolf-arena/game-text";
import { REPLAY_TIME_ZONES, type ReplayDisplayOptions } from "./replay-display";

export function ReplayDisplayControls({
  display,
  onChange,
}: {
  display: ReplayDisplayOptions;
  onChange: (next: Partial<ReplayDisplayOptions>) => void;
}) {
  return (
    <div className="display-controls">
      <label>
        {text(display.locale, "replay.language")}
        <select
          aria-label={text(display.locale, "replay.language")}
          value={display.locale}
          onChange={(event) => onChange({ locale: event.target.value === "en" ? "en" : "zh-CN" })}
        >
          <option value="zh-CN">中文</option>
          <option value="en">English</option>
        </select>
      </label>
      <label>
        {text(display.locale, "replay.timezone")}
        <select
          aria-label={text(display.locale, "replay.timezone")}
          value={display.timeZone}
          onChange={(event) => onChange({ timeZone: event.target.value })}
        >
          {!REPLAY_TIME_ZONES.some((zone) => zone === display.timeZone) && (
            <option value={display.timeZone}>{display.timeZone}</option>
          )}
          {REPLAY_TIME_ZONES.map((zone) => (
