controls.text:
/**
 * 负责从已读复盘和显示选项构建当前帧的纯画面数据。输入为复盘、帧进度与时间／语言设置；输出为原阶段、玩家和结果展示信息。保留原校验和投影顺序，不依赖工作台交互状态，也不写入归档。
 */
import { readReplayArchive, ReplayDocumentValidationError, type ReplayDocument, type RecordingEnvelope } from "@ai-werewolf-arena/replay-contract";
import { text } from "@ai-werewolf-arena/game-text";
import { victoryPointLabel, supportsGamePresentation } from "@ai-werewolf-arena/game-presentation";
import {
  formatReplayTime,
  validateReplayDisplay,
  DEFAULT_REPLAY_TIME_ZONE,
  type ReplayDisplayOptions,
} from "./replay-display";
import { buildPresentationReplay, type PresentationReplay } from "./replay-presentation";
import { buildReplaySnapshot } from "./replay-projection";
import { eventLabel } from "./event-labels";
import { phaseName, roleName, eventStageName } from "./replay-localization";

export const FRAMES_PER_EVENT = 90;
export type ReplayRenderInput = ReplayDisplayOptions & { replay: PresentationReplay };
/** 离线画面输入不依赖工作台焦点、播放状态、运行时钟或宿主时区；直接新封装也必须核对展示声明。 */
export function createReplayRenderInput(
  replay: ReplayDocument | RecordingEnvelope<ReplayDocument>,
  display?: ReplayDisplayOptions,
): ReplayRenderInput {
  const archive = readReplayArchive(replay);
  if (archive.identities && !supportsGamePresentation(archive.identities.presentation))
    throw new ReplayDocumentValidationError("unsupported_version", "identities.presentation");
  const canonical = archive.replay;
  const options = display ?? {
    locale: canonical.meta.locale ?? "zh-CN",
    timeZone: DEFAULT_REPLAY_TIME_ZONE,
  };
  validateReplayDisplay(options);
  return {
    replay: buildPresentationReplay(canonical),
    locale: options.locale,
    timeZone: options.timeZone,
  };
}
export function buildReplayFrame(input: ReplayRenderInput, frame: number) {
  validateReplayDisplay(input);
  if (!Number.isSafeInteger(frame) || frame < 0) throw new Error("replay_frame_invalid");
  const { replay, locale } = input;
  const eventIndex = Math.min(Math.floor(frame / FRAMES_PER_EVENT), replay.events.length - 1);
  const snapshot = buildReplaySnapshot(replay, eventIndex);
  const event = snapshot.event;
  return {
    eventIndex,
    eventSeq: event?.seq ?? null,
    snapshot,
    dayPhase: text(locale, "replay.day_phase", {
      day: snapshot.day,
      phase: phaseName(snapshot.phase, locale),
    }),
    stage: event
      ? eventStageName(
          event,
          locale,
          replay.players.map((player) => player.player_id),
        )
      : text(locale, "replay.start"),
    label: event
      ? eventLabel(
          event,
          locale,
          replay.players.map((player) => player.player_id),
        )
      : text(locale, "replay.no_events"),
    time: formatReplayTime(event?.timestamp, input),
    victory: snapshot.decision ? victoryPointLabel(snapshot.decision.decidedAt, locale) : null,
    winnerLabel: text(locale, "victory.winner_badge"),
    players: snapshot.players.map((player) => ({
      ...player,
      roleLabel: roleName(
        player.role === "unknown" && player.publicRole ? player.publicRole : player.role,
        locale,
      ),
      sheriffLabel: player.isSheriff ? text(locale, "replay.sheriff") : "",
    })),
  };
}

/**
 * 负责按事件游标把复盘事实投影为席位与当前阶段。输入为原归档和事件索引，输出画面状态副本。
 * 投影消费共享事实 reader，不执行后端规则、不推进真实对局或把画面状态当行动许可。
 */
import { type ReplayDocument, type ReplayEvent } from "@ai-werewolf-arena/replay-contract";
import { readReplayEvent, readReplayEventEnvelope } from "./replay-event-reader";
import type { SealedVictoryResult } from "@ai-werewolf-arena/game-contract";

export interface ReplayPlayerState {
  playerId: number;
  name?: string;
  role: string;
  camp: string;
  alive: boolean;
  isSheriff: boolean;
  isWinner: boolean;
  publicRole?: string;
}

export interface ReplaySnapshot {
  event: ReplayEvent | null;
  players: ReplayPlayerState[];
  day: number;
  phase: string;
  decision: SealedVictoryResult | null;
}

export function buildReplaySnapshot(
  replay: Pick<ReplayDocument, "players" | "events">,
  eventIndex: number,
): ReplaySnapshot {
  const states = new Map(
    replay.players.map((player) => [
      player.player_id,
      {
        playerId: player.player_id,
        ...(player.name === undefined ? {} : { name: player.name }),
        role: player.role,
        camp: player.camp,
        alive: true,
        isSheriff: false,
        isWinner: false,
      },
    ]),
  );
  const lastIndex = Math.min(Math.max(eventIndex, 0), replay.events.length - 1);
  let decision: SealedVictoryResult | null = null;

  const markDead = (playerId: number | null) => {
    if (playerId !== null && states.has(playerId)) states.get(playerId)!.alive = false;
  };

  const playerIds = [...states.keys()];
  let event: ReplayEvent | null = null,
    day = 0,
    phase = "night";
  for (const raw of replay.events.slice(0, lastIndex + 1)) {
    const fact = readReplayEvent(raw, playerIds);
    event = fact?.event ?? readReplayEventEnvelope(raw);
    if (fact) {
      day = fact.event.day;
      phase = fact.event.phase;
    }
    for (const effect of fact?.effects ?? []) {
      switch (effect.kind) {
        case "camp_changed":
          states.get(effect.playerId)!.camp = effect.camp;
          break;
        case "identity_changed":
          states.get(effect.playerId)!.role = effect.role;
          states.get(effect.playerId)!.camp = effect.camp;
          break;
        case "role_revealed":
          (states.get(effect.playerId)! as ReplayPlayerState).publicRole = effect.role;
          break;
        case "deaths":
          for (const playerId of effect.playerIds) markDead(playerId);
          break;
        case "sheriff_elected":
          for (const player of states.values())
            player.isSheriff = player.playerId === effect.playerId;
          break;
        case "sheriff_transferred":
          states.get(effect.fromId)!.isSheriff = false;
          states.get(effect.toId)!.isSheriff = true;
          break;
        case "sheriff_destroyed":
          states.get(effect.playerId)!.isSheriff = false;
          break;
        case "victory": {
          decision = effect.decision;
          const winners =
            decision.outcome.kind === "victory" ? decision.outcome.winningPlayerIds : [];
          for (const player of states.values()) player.isWinner = winners.includes(player.playerId);
          break;
        }
      }
    }
  }

  return {
    event,
    players: [...states.values()].sort((left, right) => left.playerId - right.playerId),
    day,
    phase,
    decision,
  };
}

/**
 * 负责离线文件与本地 API 的复盘读取；输入为用户原文件或响应，输出为原规范 ReplayDocument 与结构化错误。
 * 显式新封装必须由真实展示 owner 支持；历史未声明／v1／v2继续原转换，不补造版本或改写用户原文。
 * 本模块不执行游戏、验证真实源码或授予严格复现兼容；视频入口也消费同一 reader。
 */
import { supportsGamePresentation } from "@ai-werewolf-arena/game-presentation";
import type { ReplayDocument } from "@ai-werewolf-arena/replay-contract";
import {
  readReplayArchive,
  ReplayDocumentValidationError,
} from "@ai-werewolf-arena/replay-contract";
import { renderMessage, type Locale, type MessageRef } from "@ai-werewolf-arena/game-text";

export class ReplayLoadError extends Error {
  constructor(
    readonly messageRef: MessageRef,
    locale: Locale = "zh-CN",
  ) {
    super(renderMessage(locale, messageRef));
    this.name = "ReplayLoadError";
  }
}
export type ReplayLoadState =
  | { status: "loading" }
  | { status: "ready"; replay: ReplayDocument }
  | { status: "missing" }
  | { status: "error"; message: MessageRef };

export function parseOfflineReplayJson(raw: string): ReplayDocument {
  let value: unknown;
  try {
    value = JSON.parse(raw);
  } catch {
    throw new ReplayLoadError({ key: "replay.invalid_file" });
  }
  try {
    const archive = readReplayArchive(value);
    // 只检查当前 renderer 实际拥有的格式；没有声明的旧档不被伪装成当前发布版本。
    if (archive.identities && !supportsGamePresentation(archive.identities.presentation))
      throw new ReplayDocumentValidationError("unsupported_version", "identities.presentation");
    return archive.replay;
  } catch (error) {
    const key =
      error instanceof ReplayDocumentValidationError && error.kind === "missing_fields"
        ? "replay.missing_fields"
        : error instanceof ReplayDocumentValidationError && error.kind === "unsupported_version"
          ? "replay.unsupported_version"
          : "replay.invalid_file";
    throw new ReplayLoadError({ key });
  }
}
export async function readOfflineReplay(file: File): Promise<ReplayDocument> {
  try {
    return parseOfflineReplayJson(await file.text());
  } catch (error) {
    throw error instanceof ReplayLoadError
      ? error
      : new ReplayLoadError({ key: "replay.read_failed" });
  }
}
export async function loadReplay(): Promise<ReplayLoadState> {
  try {
    const response = await fetch("/api/replay");
    if (response.status === 404) return { status: "missing" };
    if (!response.ok)
      throw new ReplayLoadError({
        key: "replay.http_failed",
        parameters: { status: response.status },
      });
    return { status: "ready", replay: parseOfflineReplayJson(await response.text()) };
  } catch (error) {
    return {
      status: "error",
      message: error instanceof ReplayLoadError ? error.messageRef : { key: "replay.read_failed" },
    };
  }
}

/**
 * 负责复盘显示语言／时区校验和时间文案。输入为归档时间与明确展示选项，输出原格式文本或原错误。
 * 历史无时区时间保持原文，不借宿主时区解释；本层不修改归档、播放器状态或游戏许可。
 */
import { isLocale } from "@ai-werewolf-arena/game-contract";
import type { Locale } from "@ai-werewolf-arena/game-text";

export type ReplayDisplayOptions = { locale: Locale; timeZone: string };
export const DEFAULT_REPLAY_TIME_ZONE = "UTC";
export const REPLAY_TIME_ZONES = [
  "UTC",
  "Asia/Shanghai",
  "America/New_York",
  "Europe/London",
] as const;
export function validateReplayDisplay(options: ReplayDisplayOptions): void {
  if (!isLocale(options.locale)) throw new Error("replay_display_locale_invalid");
  if (typeof options.timeZone !== "string" || !options.timeZone.trim())
    throw new Error("replay_display_time_zone_invalid");
  try {
    new Intl.DateTimeFormat(options.locale, { timeZone: options.timeZone });
  } catch {
    throw new Error("replay_display_time_zone_invalid");
  }
}
/** 无时区的历史时间保持原文，不按宿主时区解释。 */
export function formatReplayTime(
  timestamp: string | undefined,
  options: ReplayDisplayOptions,
): string {
  validateReplayDisplay(options);
  if (!timestamp) return "—";
  if (!/(?:Z|[+-]\d{2}:?\d{2})$/i.test(timestamp)) return timestamp;
  const date = new Date(timestamp);
  if (Number.isNaN(date.valueOf())) return timestamp;
  const parts = new Intl.DateTimeFormat(options.locale, {
    timeZone: options.timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);
  const part = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((item) => item.type === type)!.value;
  return `${part("year")}-${part("month")}-${part("day")} ${part("hour")}:${part("minute")}:${part("second")} [${options.timeZone}]`;
}
